window.futvizVista("cantidad-calidad","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"cantidad-calidad\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"cantidad-calidad\"]={\"id\":\"cantidad-calidad\",\"titulo\":\"Cantidad vs. calidad de los tiros\",\"bajada\":\"A la derecha, m\u00e1s tiros por partido; arriba, m\u00e1s xG por tiro. Las l\u00edneas dejan al 20% con m\u00e1s de cada uno.\",\"pregunta\":\"\u00bfDispara mucho o espera la ocasi\u00f3n clara?\",\"tabla\":\"equipos\",\"entidad\":\"equipos\",\"x\":{\"col\":\"tiros_pp\",\"label\":\"Tiros por partido (sin penales)\",\"corto\":\"Tiros por partido\",\"dec\":1},\"y\":{\"col\":\"xg_tiro\",\"label\":\"xG por tiro (sin penales)\",\"corto\":\"xG por tiro\",\"dec\":3},\"referencia\":{\"tipo\":\"promedios\",\"cuadrantes\":{\"tr\":\"Muchos tiros y buena calidad\",\"tl\":\"Pocos tiros pero buena calidad\",\"br\":\"Muchos tiros pero poca calidad\",\"bl\":\"Pocos tiros y poca calidad\"},\"cuantil\":0.8},\"requiere\":[\"tiros_pp\",\"xg_tiro\"],\"subtitulo\":\"Equipos de las 5 ligas \u00b7 {temporada} \u00b7 por partido, sin penales\",\"filtros\":{\"nivel\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"Tiros por partido\",\"ayuda\":\"Ordenados por Tiros por partido (sin penales)\"},{\"id\":\"y\",\"etiqueta\":\"xG por tiro\",\"ayuda\":\"Ordenados por xG por tiro (sin penales)\"}],\"queMirar\":\"Arriba a la derecha, los que disparan mucho y con ocasiones de calidad. Las l\u00edneas marcan el 20% m\u00e1s alto de cada eje. **Arriba a la izquierda**: pocos tiros pero de buena calidad. **Abajo a la derecha**: muchos tiros pero de poca calidad. **Abajo a la izquierda**: pocos tiros y de poca calidad.\\n\\nLos dos ejes multiplicados dan el xG a favor por partido de \u00abOcasiones a favor y en contra\u00bb: un mismo xG se alcanza disparando mucho de baja calidad o poco de alta. Haz clic en un cuadrante para acercarte a esos equipos.\",\"insight\":\"cantidad_calidad\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"]};</script>");